#include <iostream>

class RegistroConTraza {
public:
    explicit RegistroConTraza(int numero) : numero_{numero} {
        std::cout << "R+" << numero_ << '|';
    }
    ~RegistroConTraza() { std::cout << "R-" << numero_ << '|'; }
private:
    int numero_;
};

class TrazaA : virtual public RegistroConTraza {
public:
    explicit TrazaA(int numero) : RegistroConTraza{numero} {
        std::cout << "A+|";
    }
    ~TrazaA() { std::cout << "A-|"; }
};

class TrazaB : virtual public RegistroConTraza {
public:
    explicit TrazaB(int numero) : RegistroConTraza{numero} {
        std::cout << "B+|";
    }
    ~TrazaB() { std::cout << "B-|"; }
};

class Marca {
public:
    Marca() { std::cout << "M+|"; }
    ~Marca() { std::cout << "M-|"; }
};

class EncuentroConTraza : public TrazaA, public TrazaB {
public:
    explicit EncuentroConTraza(int numero)
        : RegistroConTraza{numero}, TrazaA{10}, TrazaB{20}, marca_{} {
        std::cout << "E+|";
    }
    ~EncuentroConTraza() { std::cout << "E-|"; }
private:
    Marca marca_;
};
int main() {
    {
        EncuentroConTraza dato{5};
        std::cout << "Uso|";
    }
    std::cout << "Fin";
    return 0;
}

